def ScalarShiftAcceptedOffCountable (𝒜 : Set (Set ℕ)) (M : ScalarMatrix 𝕜) : Prop :=
  ∃ C : Set (Set ℕ), C.Countable ∧ ∃ a : 𝕜,
    Accepts 𝕜 (𝒜 \ C) (𝒜 \ C) (M - a • identityMatrix 𝕜)

